CREATE TABLE IF NOT EXISTS economic_consensus_reconciliation_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL, previous_score numeric, consensus_score numeric NOT NULL DEFAULT 0, evidence_score numeric NOT NULL DEFAULT 0, verification_score numeric NOT NULL DEFAULT 0, network_score numeric NOT NULL DEFAULT 0, agreement_score numeric NOT NULL DEFAULT 0, state text NOT NULL DEFAULT 'developing', reasons jsonb NOT NULL DEFAULT '[]'::jsonb, changes jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now())